package com.greenocean.backend.trust;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;
/** Purpose-specific technical aggregates; never a mental-health or clinical outcome score. */
@Service @org.springframework.transaction.annotation.Transactional
public class ServiceQuality {
 private final JdbcTemplate db;private final IncidentOperations operations;private final SafeTelemetry telemetry;private final TrustAuthority authority;
 public ServiceQuality(JdbcTemplate db,IncidentOperations operations,SafeTelemetry telemetry,TrustAuthority authority){this.db=db;this.operations=operations;this.telemetry=telemetry;this.authority=authority;}
 public Map<String,Object> summary(UUID who,UUID sid,String domain){operations.require(who,sid,domain);var r=new LinkedHashMap<String,Object>();r.put("domain",domain);r.put("clinicalOutcomeMeasurement",false);r.put("humanResponseGuaranteed",false);r.put("coordination",db.queryForList("SELECT state,count(*) AS count FROM trust_cases WHERE domain=? GROUP BY state ORDER BY state",domain));r.put("incidents",db.queryForList("SELECT state,severity,count(*) AS count FROM operation_incidents WHERE domain=? GROUP BY state,severity ORDER BY state,severity",domain));
  switch(domain){
   case"SOCIAL","GROUP"->{r.put("reportScope","Imported source reports only; uncoordinated reports are not counted");r.put("reports",db.queryForList("SELECT r.status,count(*) AS count,EXTRACT(EPOCH FROM(CURRENT_TIMESTAMP-min(r.created_at)))::bigint AS oldest_age_seconds FROM reports r JOIN trust_cases c ON c.source_kind='REPORT' AND c.source_id=r.id WHERE c.domain=? GROUP BY r.status ORDER BY r.status",domain));}
   case"LISTENER"->{r.put("queue",db.queryForList("SELECT status,count(*) AS count FROM listener_wait_queue GROUP BY status ORDER BY status"));r.put("sessions",db.queryForList("SELECT status,count(*) AS count FROM live_support_requests GROUP BY status ORDER BY status"));r.put("coverageState","Current source qualification/readiness and coverage gates remain authoritative; scheduled hours are not guaranteed presence");}
   case"CLINIC"->{r.put("appointments",db.queryForList("SELECT status,count(*) AS count FROM consultation_requests WHERE clinic_governed GROUP BY status ORDER BY status"));r.put("encounters",db.queryForList("SELECT state,count(*) AS count FROM clinic_encounters GROUP BY state ORDER BY state"));r.put("feedback","Voluntary source P4 feedback only; technical reliability is not therapy effectiveness");if(authority.has(who,"CLINIC_REPUTATION_OPERATOR")){int n=db.queryForObject("SELECT count(DISTINCT f.patient_id) FROM clinic_feedback f JOIN consultation_requests c ON c.id=f.appointment_id JOIN clinic_encounters e ON e.id=f.encounter_id JOIN clinic_feedback_versions v ON v.feedback_id=f.id AND v.revision=f.revision WHERE f.state IN('APPROVED','PUBLISHED') AND c.status='COMPLETED' AND e.started_at IS NOT NULL AND e.ended_at>e.started_at AND v.include_aggregate",Integer.class);r.put("verifiedFeedbackSampleBand",n>=5?"AT_LEAST_FIVE_VOLUNTARY_PARTICIPANTS":"INSUFFICIENT_EVIDENCE");}}
   case"FINANCE"->{r.put("paymentStates",db.queryForList("SELECT state,count(*) AS count FROM clinic_payment_intents GROUP BY state ORDER BY state"));r.put("refundStates",db.queryForList("SELECT state,count(*) AS count FROM clinic_refunds GROUP BY state ORDER BY state"));}
   case"EDUCATION"->r.put("publication",db.queryForList("SELECT retired,count(*) AS count FROM growth_resources GROUP BY retired ORDER BY retired"));
   case"ACCOUNT"->r.put("privateWellbeing","No journal, mood, reflection or private answer is inspected to infer satisfaction, distress or clinical outcomes");
   case"PLATFORM"->r.put("technicalTelemetry",telemetry.snapshot());
   default->throw new IllegalArgumentException("Choose an operational service purpose");
  }Set<String> buckets=switch(domain){case"SOCIAL"->Set.of("SOCIAL");case"GROUP"->Set.of("GROUP");case"LISTENER"->Set.of("LISTENER");case"CLINIC"->Set.of("CLINIC");case"EDUCATION"->Set.of("EDUCATION");case"ACCOUNT"->Set.of("AUTH","WELLBEING","WELLBEING_WRITE","ACCOUNT_EXPORT","ACCOUNT_ERASURE");case"PLATFORM"->Set.of("TRUST","HEALTH","OTHER");default->Set.of();};var snapshot=telemetry.snapshot();@SuppressWarnings("unchecked")var counts=(List<Map<String,Object>>)snapshot.get("rows");r.put("technicalRequests",Map.of("enabled",snapshot.get("enabled"),"rows",counts.stream().filter(row->buckets.contains(row.get("service"))).toList(),"notice","Process-local technical request response families; accepted erasure is not proof that external files or backups were erased"));return r;
 }
}
